impl IRBuildable for Unit {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            Unit::Decl(d) => d.build(program, my_ir_generator_info),
            Unit::FuncDef(f) => f.build(program, my_ir_generator_info),
        }
    }
