fn get_valuedata(
    value: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> ValueData {
    if value.is_global() {
        program.borrow_value(value).clone()
    } else {
        program
            .func(my_ir_generator_info.curr_func.unwrap())
            .dfg()
            .value(value)
            .clone()
    }
}

/// Helper function to build a new value.
fn create_new_local_value<'a>(
    program: &'a mut Program,
    my_ir_generator_info: &'a mut MyIRGeneratorInfo,
) -> koopa::ir::builder::LocalBuilder<'a> {
    program
        .func_mut(
            my_ir_generator_info
                .curr_func
                .expect("You should use create_new_global_value when curr_func is None! "),
        )
        .dfg_mut()
        .new_value()
}

/// Helper function to build a new basic block.
fn create_new_block<'a>(
    program: &'a mut Program,
    my_ir_generator_info: &'a mut MyIRGeneratorInfo,
    name: &str,
) -> BasicBlock {
    let block = program
        .func_mut(my_ir_generator_info.curr_func.unwrap())
        .dfg_mut()
        .new_bb()
        .basic_block(Some(format!("%bb{}_{}", my_ir_generator_info.bb_cnt, name)));
    my_ir_generator_info.bb_cnt += 1;
    block
}

/// Helper function to insert instructions into the current function's data flow graph.
fn insert_local_instructions<T>(
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
    instructions: T,
) where
    T: IntoIterator<Item = Value>,
{
    program
        .func_mut(my_ir_generator_info.curr_func.unwrap())
        .layout_mut()
        .bb_mut(my_ir_generator_info.curr_block.unwrap())
        .insts_mut()
        .extend(instructions);
}

/// Helper function to insert basic blocks into the current function's data flow graph.
fn insert_basic_blocks<T>(
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
    basic_blocks: T,
) where
    T: IntoIterator<Item = BasicBlock>,
{
    program
        .func_mut(my_ir_generator_info.curr_func.unwrap())
        .layout_mut()
        .bbs_mut()
        .extend(basic_blocks);
}

fn build_shape(
    shape_exps: &Vec<Exp>,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<Vec<usize>, String> {
    let mut result = vec![];
    for exp in shape_exps {
        match exp.build(program, my_ir_generator_info)? {
            IRExpBuildResult::Const(int) => result.push(int as usize),
            IRExpBuildResult::Value(_) => {
                return Err(format!("The shape of array must be constant! "))
            }
        }
    }
    Ok(result.clone())
}

fn get_array_type(btype: &BType, shape: &[usize]) -> TypeKind {
    if shape.is_empty() {
        return btype.content.clone();
    }
    let inner_typekind = get_array_type(btype, &shape[1..]);
    TypeKind::Array(Type::get(inner_typekind), shape[0])
}

