        | ValueKind::Store(..)
        | ValueKind::GetPtr(..)
        | ValueKind::GetElemPtr(..)
        | ValueKind::Binary(..)
        | ValueKind::Branch(..)
        | ValueKind::Jump(..)
        | ValueKind::Call(..)
        | ValueKind::Return(..)
    )
