//! Build a single component into Koopa IR.

use crate::ast_def::{expressions::LVal, statements::*};
use koopa::ir::{builder_traits::*, Program, TypeKind, Value};

use super::{
    build_expressions::{IRExpBuildResult, IRExpBuildable},
    create_new_block, create_new_local_value, get_valuedata, insert_basic_blocks,
    insert_local_instructions, IRBuildResult, IRBuildable, MyIRGeneratorInfo, SymbolTableEntry,
};

fn create_i32_const(
    value: i32,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    create_new_local_value(program, my_ir_generator_info).integer(value)
}

fn build_exp_value(
    result: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    match result {
        IRExpBuildResult::Const(int) => create_i32_const(int, program, my_ir_generator_info),
        IRExpBuildResult::Value(value) => value,
    }
}

fn build_lval_addr(
    lval: &LVal,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<Value, String> {
    let LVal::Default(ident, index_exps) = lval;
    let ptr = match my_ir_generator_info.symbol_tables.get(&ident.content) {
        Some(SymbolTableEntry::Variable(_, ptr)) => *ptr,
        Some(SymbolTableEntry::Constant(_, _)) => {
            return Err(format!("Can not assign to constant '{}'", ident.content))
        }
        None => return Err(format!("Undeclared LVal symbol: {}", ident.content)),
    };

    let mut curr = ptr;
    let mut curr_ty = get_valuedata(curr, program, my_ir_generator_info).ty().clone();
    let mut first_pointer_index = false;
    if let TypeKind::Pointer(inner) = curr_ty.kind() {
        if matches!(inner.kind(), TypeKind::Pointer(_)) {
            if index_exps.is_empty() {
                return Err(format!("Can not assign to array parameter '{}'", ident.content));
            }
            let load = create_new_local_value(program, my_ir_generator_info).load(curr);
            insert_local_instructions(program, my_ir_generator_info, [load]);
            curr = load;
            curr_ty = get_valuedata(curr, program, my_ir_generator_info).ty().clone();
            first_pointer_index = true;
        }
    }

    for exp in index_exps {
        let index = build_exp_value(
            exp.build(program, my_ir_generator_info)?,
            program,
            my_ir_generator_info,
        );
        let next = if first_pointer_index {
            first_pointer_index = false;
            create_new_local_value(program, my_ir_generator_info).get_ptr(curr, index)
        } else {
            match curr_ty.kind() {
                TypeKind::Pointer(base) if matches!(base.kind(), TypeKind::Array(_, _)) => {
                    create_new_local_value(program, my_ir_generator_info).get_elem_ptr(curr, index)
                }
                _ => {
                    return Err(format!(
                        "Indexing non-array lvalue '{}': {:?}",
                        ident.content, curr_ty
                    ))
                }
            }
        };
        insert_local_instructions(program, my_ir_generator_info, [next]);
        curr = next;
        curr_ty = get_valuedata(curr, program, my_ir_generator_info).ty().clone();
    }

    Ok(curr)
}

impl IRBuildable for Stmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match &self {
            Stmt::UnmatchedStmt(stmt) => stmt.build(program, my_ir_generator_info),
            Stmt::MatchedStmt(stmt) => stmt.build(program, my_ir_generator_info),
        }
    }
}

impl IRBuildable for UnmatchedStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        self.default.build(program, my_ir_generator_info)
    }
}

impl IRBuildable for MatchedStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        self.default.build(program, my_ir_generator_info)
    }
}

impl IRBuildable for BasicStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            BasicStmt::AssignStmt(lval, exp) => {
                let addr = build_lval_addr(lval, program, my_ir_generator_info)?;
                let dest_ty = match get_valuedata(addr, program, my_ir_generator_info).ty().kind() {
                    TypeKind::Pointer(base) => base.clone(),
                    _ => return Err(format!("Invalid assignment destination: {:?}", lval)),
                };
                if !dest_ty.is_i32() {
                    return Err(format!("Can not assign to aggregate lvalue: {:?}", lval));
                }
                let value = build_exp_value(
                    exp.build(program, my_ir_generator_info)?,
                    program,
                    my_ir_generator_info,
                );
                if !get_valuedata(value, program, my_ir_generator_info).ty().is_i32() {
                    return Err(format!("Assignment value must be i32: {:?}", exp));
                }
                let store = create_new_local_value(program, my_ir_generator_info).store(value, addr);
                insert_local_instructions(program, my_ir_generator_info, [store]);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Exp(exp) => {
                if let Some(exp) = exp {
                    exp.build(program, my_ir_generator_info)?;
                }
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Block(block) => {
                my_ir_generator_info.symbol_tables.add_new_table();
                block.build(program, my_ir_generator_info)
            }
            BasicStmt::IfStmt(cond, then_stmt, else_stmt) => {
                match cond.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        if int != 0 {
                            then_stmt.build(program, my_ir_generator_info)
                        } else if let Some(else_stmt) = else_stmt.as_ref() {
                            else_stmt.build(program, my_ir_generator_info)
                        } else {
                            Ok(IRBuildResult::OK)
                        }
                    }
                    IRExpBuildResult::Value(cond_value) => {
                        if !get_valuedata(cond_value, program, my_ir_generator_info).ty().is_i32() {
                            return Err(format!("Condition must be i32: {:?}", cond));
                        }
                        if let Some(else_stmt) = else_stmt.as_ref() {
                            let then_bb = create_new_block(program, my_ir_generator_info, "if_then");
                            let else_bb = create_new_block(program, my_ir_generator_info, "if_else");
                            insert_basic_blocks(program, my_ir_generator_info, [then_bb, else_bb]);
                            let br = create_new_local_value(program, my_ir_generator_info)
                                .branch(cond_value, then_bb, else_bb);
                            insert_local_instructions(program, my_ir_generator_info, [br]);

                            my_ir_generator_info.curr_block = Some(then_bb);
                            let then_result = then_stmt.build(program, my_ir_generator_info)?;
                            let then_tail = my_ir_generator_info.curr_block.unwrap();

                            my_ir_generator_info.curr_block = Some(else_bb);
                            let else_result = else_stmt.build(program, my_ir_generator_info)?;
                            let else_tail = my_ir_generator_info.curr_block.unwrap();

                            let then_stops = matches!(then_result, IRBuildResult::EARLYSTOPPING);
                            let else_stops = matches!(else_result, IRBuildResult::EARLYSTOPPING);
                            if then_stops && else_stops {
                                return Ok(IRBuildResult::EARLYSTOPPING);
                            }

                            let end_bb = create_new_block(program, my_ir_generator_info, "if_end");
                            insert_basic_blocks(program, my_ir_generator_info, [end_bb]);
                            if !then_stops {
                                my_ir_generator_info.curr_block = Some(then_tail);
                                let jump =
                                    create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                                insert_local_instructions(program, my_ir_generator_info, [jump]);
                            }
                            if !else_stops {
                                my_ir_generator_info.curr_block = Some(else_tail);
                                let jump =
                                    create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                                insert_local_instructions(program, my_ir_generator_info, [jump]);
                            }
                            my_ir_generator_info.curr_block = Some(end_bb);
                            Ok(IRBuildResult::OK)
                        } else {
                            let then_bb = create_new_block(program, my_ir_generator_info, "if_then");
                            let end_bb = create_new_block(program, my_ir_generator_info, "if_end");
                            insert_basic_blocks(program, my_ir_generator_info, [then_bb, end_bb]);
                            let br = create_new_local_value(program, my_ir_generator_info)
                                .branch(cond_value, then_bb, end_bb);
                            insert_local_instructions(program, my_ir_generator_info, [br]);

                            my_ir_generator_info.curr_block = Some(then_bb);
                            let then_result = then_stmt.build(program, my_ir_generator_info)?;
                            if !matches!(then_result, IRBuildResult::EARLYSTOPPING) {
                                let jump =
                                    create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                                insert_local_instructions(program, my_ir_generator_info, [jump]);
                            }
                            my_ir_generator_info.curr_block = Some(end_bb);
                            Ok(IRBuildResult::OK)
                        }
                    }
                }
            }
            BasicStmt::WhileStmt(cond, body) => {
                let cond_bb = create_new_block(program, my_ir_generator_info, "while_cond");
                let body_bb = create_new_block(program, my_ir_generator_info, "while_body");
                let end_bb = create_new_block(program, my_ir_generator_info, "while_end");
                let jump_to_cond =
                    create_new_local_value(program, my_ir_generator_info).jump(cond_bb);
                insert_local_instructions(program, my_ir_generator_info, [jump_to_cond]);
                insert_basic_blocks(program, my_ir_generator_info, [cond_bb, body_bb, end_bb]);

                my_ir_generator_info.break_tgt_blocks.push(end_bb);
                my_ir_generator_info.continue_tgt_blocks.push(cond_bb);

                my_ir_generator_info.curr_block = Some(cond_bb);
                match cond.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        let jump = create_new_local_value(program, my_ir_generator_info)
                            .jump(if int != 0 { body_bb } else { end_bb });
                        insert_local_instructions(program, my_ir_generator_info, [jump]);
                    }
                    IRExpBuildResult::Value(cond_value) => {
                        if !get_valuedata(cond_value, program, my_ir_generator_info).ty().is_i32() {
                            return Err(format!("Condition must be i32: {:?}", cond));
                        }
                        let br = create_new_local_value(program, my_ir_generator_info)
                            .branch(cond_value, body_bb, end_bb);
                        insert_local_instructions(program, my_ir_generator_info, [br]);
                    }
                }

                my_ir_generator_info.curr_block = Some(body_bb);
                let body_result = body.build(program, my_ir_generator_info)?;
                if !matches!(body_result, IRBuildResult::EARLYSTOPPING) {
                    let jump_back =
                        create_new_local_value(program, my_ir_generator_info).jump(cond_bb);
                    insert_local_instructions(program, my_ir_generator_info, [jump_back]);
                }

                my_ir_generator_info.break_tgt_blocks.pop();
                my_ir_generator_info.continue_tgt_blocks.pop();
                my_ir_generator_info.curr_block = Some(end_bb);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::BreakStmt => {
                let target = my_ir_generator_info
                    .break_tgt_blocks
                    .last()
                    .copied()
                    .ok_or_else(|| "break used outside of loop".to_string())?;
                let jump = create_new_local_value(program, my_ir_generator_info).jump(target);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
            BasicStmt::ContinueStmt => {
                let target = my_ir_generator_info
                    .continue_tgt_blocks
                    .last()
                    .copied()
                    .ok_or_else(|| "continue used outside of loop".to_string())?;
                let jump = create_new_local_value(program, my_ir_generator_info).jump(target);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
            BasicStmt::ReturnStmt(exp) => {
                let ret_ty = match program.func(my_ir_generator_info.curr_func.unwrap()).ty().kind() {
                    TypeKind::Function(_, ret_ty) => ret_ty.clone(),
                    _ => return Err("Current symbol is not a function".to_string()),
                };
                let ret = match exp {
                    Some(exp) => {
                        if ret_ty.is_unit() {
                            return Err(format!("Void function can not return a value: {:?}", exp));
                        }
                        let value = build_exp_value(
                            exp.build(program, my_ir_generator_info)?,
                            program,
                            my_ir_generator_info,
                        );
                        if !get_valuedata(value, program, my_ir_generator_info).ty().is_i32() {
                            return Err(format!("Return value must be i32: {:?}", exp));
                        }
                        create_new_local_value(program, my_ir_generator_info).ret(Some(value))
                    }
                    None => {
                        if !ret_ty.is_unit() {
                            return Err("Non-void function must return a value".to_string());
                        }
                        create_new_local_value(program, my_ir_generator_info).ret(None)
                    }
                };
                insert_local_instructions(program, my_ir_generator_info, [ret]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
        }
    }
}

