pub enum IRBuildResult {
    OK,
    EARLYSTOPPING,
}

pub trait IRBuildable {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String>;
}

impl IRBuildable for CompUnit {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let builtin_decls = [
            ("getint", vec![], Type::get_i32()),
            ("getch", vec![], Type::get_i32()),
            (
                "getarray",
                vec![Type::get_pointer(Type::get_i32())],
                Type::get_i32(),
            ),
            ("putint", vec![Type::get_i32()], Type::get_unit()),
            ("putch", vec![Type::get_i32()], Type::get_unit()),
            (
                "putarray",
                vec![Type::get_i32(), Type::get_pointer(Type::get_i32())],
                Type::get_unit(),
            ),
            ("starttime", vec![], Type::get_unit()),
            ("stoptime", vec![], Type::get_unit()),
        ];
        for (name, params, ret) in builtin_decls {
            let func = program.new_func(FunctionData::new_decl(format!("@{}", name), params, ret));
            my_ir_generator_info
                .function_table
                .insert(name.to_string(), func);
        }

        let CompUnit::Default(units) = self;
        for unit in units {
            if let Unit::FuncDef(crate::ast_def::declarations::FuncDef::Default(
                ret_type,
                ident,
                params,
                _,
            )) = unit
            {
                if my_ir_generator_info.function_table.contains_key(&ident.content) {
                    return Err(format!("Duplicate global symbol: {}", ident.content));
                }
                let mut param_defs = vec![];
                for param in params {
                    let crate::ast_def::declarations::FuncFParam::Default(
                        btype,
                        param_ident,
                        shape_exps,
                    ) = param;
                    let param_ty = match shape_exps {
                        None => Type::get(btype.content.clone()),
                        Some(shape_exps) => {
                            let shape =
                                build_shape(shape_exps, program, my_ir_generator_info)?;
                            Type::get_pointer(Type::get(get_array_type(btype, &shape)))
                        }
                    };
                    param_defs.push((Some(format!("@{}", param_ident.content)), param_ty));
                }
                let func = program.new_func(FunctionData::with_param_names(
                    format!("@{}", ident.content),
                    param_defs,
                    Type::get(ret_type.content.clone()),
                ));
                my_ir_generator_info
                    .function_table
                    .insert(ident.content.clone(), func);
            }
        }
        for unit in units {
            unit.build(program, my_ir_generator_info)?;
        }
        Ok(IRBuildResult::OK)
    }
}

impl IRBuildable for Unit {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            Unit::Decl(d) => d.build(program, my_ir_generator_info),
            Unit::FuncDef(f) => f.build(program, my_ir_generator_info),
        }
    }
}

fn get_valuedata(
    value: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> ValueData {
    if value.is_global() {
        program.borrow_value(value).clone()
    } else {
        program
            .func(my_ir_generator_info.curr_func.unwrap())
            .dfg()
            .value(value)
            .clone()
            Ok(value)
        }
        _ => Err(format!("Array initializer must be an aggregate: {:?}", init)),
    }
}

